  const [selectedReferral, setSelectedReferral] = useState<Referral>(initialReferrals[0]);
  const [step, setStep] = useState(0);
  const [patient, setPatient] = useState({ name: '', phone: '', gender: '', age: '' });
  const [chosen, setChosen] = useState<string[]>([]);
  const [branch, setBranch] = useState('Ikeja');
